<script setup>import{Link,useForm}from'@inertiajs/vue3';const form=useForm({name:'',email:'',phone:'',password:'',password_confirmation:''});</script><template><div class="flex min-h-screen items-center justify-center bg-slate-950 p-4"><form class="w-full max-w-md rounded-[10px] bg-white p-6" @submit.prevent="form.post('/register')"><img src="/assets/prinx-logo.svg" class="h-10"><h1 class="mt-6 text-2xl font-black">Create account</h1><div class="mt-5 grid gap-4"><div><label class="label">Full name</label><input v-model="form.name" class="input"></div><div><label class="label">Email</label><input v-model="form.email" type="email" class="input"></div><div><label class="label">Phone</label><input v-model="form.phone" class="input"></div><div><label class="label">Password</label><input v-model="form.password" type="password" class="input"></div><div><label class="label">Confirm password</label><input v-model="form.password_confirmation" type="password" class="input"></div><button class="btn-primary" :disabled="form.processing">Create account</button></div><p class="mt-5 text-sm text-slate-500">Already registered? <Link href="/login" class="font-bold text-prinx-600">Sign in</Link></p></form></div></template>
